17	import crypto from 'crypto';
18	
19	import { stripAnsiEscapes } from '@isomorphic/stringUtils';
20	
21	import type { tools } from 'playwright-core/lib/coreBundle';
22	import type * as playwright from '../../../index';
23	import type { TestInfoImpl } from '../../worker/testInfo';
24	
25	export type BrowserMCPRequest = {
26	  initialize?: { clientInfo: tools.ClientInfo },
27	  listTools?: {},
28	  callTool?: { name: string, arguments: tools.CallToolRequest['params']['arguments'] },
29	  close?: {},
30	};
31	
32	export type BrowserMCPResponse = {
33	  initialize?: { pausedMessage: string },
34	  callTool?: tools.CallToolResult,
35	  close?: {},
36	};
37	
38	export function createCustomMessageHandler(testInfo: TestInfoImpl, context: playwright.BrowserContext) {
39	  let backend: tools.BrowserBackend | undefined;
40	  const config: tools.ContextConfig = { capabilities: ['testing'] };
41	  let tools: typeof import('playwright-core/lib/coreBundle').tools | undefined;
42	
43	  context.once('close', () => {
44	    void backend?.dispose();
45	    backend = undefined;
46	  });
47	
48	  return async (data: BrowserMCPRequest): Promise<BrowserMCPResponse> => {
49	    if (!tools)
50	      ({ tools } = require('playwright-core/lib/coreBundle') as typeof import('playwright-core/lib/coreBundle'));
51	    const toolList = tools.filteredTools(config);
52	    if (data.initialize) {
53	      if (backend)
54	        throw new Error('MCP backend is already initialized');
55	      backend = new tools.BrowserBackend(config, context, toolList);
56	      await backend.initialize(data.initialize.clientInfo);
57	      const pausedMessage = await generatePausedMessage(tools, testInfo, context);
58	      return { initialize: { pausedMessage } };
59	    }
60	
61	    if (data.callTool) {
62	      if (!backend)
63	        throw new Error('MCP backend is not initialized');
64	      return { callTool: await backend.callTool(data.callTool.name, data.callTool.arguments) };
65	    }
66	
67	    if (data.close) {
68	      await backend?.dispose();
69	      backend = undefined;
70	      return { close: {} };
71	    }
72	
73	    throw new Error('Unknown MCP request');
74	  };
75	}
76	
77	async function generatePausedMessage(tools: typeof import('playwright-core/lib/coreBundle').tools, testInfo: TestInfoImpl, context: playwright.BrowserContext) {
78	  const lines: string[] = [];
79	
80	  if (testInfo.errors.length) {
81	    lines.push(`### Paused on error:`);
82	    for (const error of testInfo.errors)
83	      lines.push(stripAnsiEscapes(error.message || ''));
84	  } else {
85	    lines.push(`### Paused at end of test. ready for interaction`);
86	  }
87	
88	  for (let i = 0; i < context.pages().length; i++) {
89	    const page = context.pages()[i];
90	    const stateSuffix = context.pages().length > 1 ? (i + 1) + ' of ' + (context.pages().length) : 'state';
91	    lines.push(
92	        '',
93	        `### Page ${stateSuffix}`,
94	        `- Page URL: ${page.url()}`,
95	        `- Page Title: ${await page.title()}`.trim()
96	    );
97	    // Only print console errors when pausing on error, not when everything works as expected.
98	    let console = testInfo.errors.length ? await tools.Tab.collectConsoleMessages(page) : [];
